209	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner == null) {
212	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	        }
214	        currentOwner.setAddress(ownerFieldsDto.getAddress());
215	        currentOwner.setCity(ownerFieldsDto.getCity());
216	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
217	        currentOwner.setLastName(ownerFieldsDto.getLastName());
218	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
219	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
220	        this.clinicService.saveOwner(currentOwner);
221	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
222	    }
